 const[t,setT]=useState('claims'); const[data,setData]=useState({providers:[],policies:[],preauthorizations:[],claims:[],patients:[]}); const[loading,setLoading]=useState(true); const[show,setShow]=useState(false); const[edit,setEdit]=useState(null);
 const load=()=>{setLoading(true);Promise.all([api('/insurance/providers'),api('/insurance/policies'),api('/insurance/preauthorizations'),api('/insurance/claims'),api('/patients')]).then(([providers,policies,preauthorizations,claims,patients])=>setData({providers,policies,preauthorizations,claims,patients})).catch(e=>notify(e.message)).finally(()=>setLoading(false))};
