 const titleMap={'opd-queue':'OPD Queue Entry','ward-transfer':'Ward Transfer','nursing-task':'Nursing Task',patient:'Patient',appointment:'Appointment',encounter:'Encounter',lab:'Laboratory Order',radiology:'Radiology Order',prescription:'Prescription',medication:'Medication',admission:'Admission',blood:'Blood Unit'};
 const editing=!!record;
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onClose()}}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><h2 id="modal-title">{editing?'Edit':'New'} {titleMap[type]}</h2><p>Changes are validated and persisted by the EasyNet HIS API.</p></div><button type="button" onClick={onClose} aria-label="Close"><X size={18}/></button></div><form onSubmit={submit} className="form-grid">
 {type==='opd-queue'&&!editing&&<>{select('patientId','Patient',patients.map(p=>({id:p.id,label:`${p.patientNumber} · ${p.firstName} ${p.lastName}`})))}{select('departmentId','Department',deps)}{select('providerId','Doctor',providers.map(p=>({id:p.id,label:`${p.firstName} ${p.lastName} · ${p.role}`})),false)}{select('priority','Priority',['NORMAL','URGENT','STAT'].map(x=>({value:x,label:x})))}{field('notes','Notes')}</>}{type==='opd-queue'&&editing&&<>{select('status','Status',['WAITING','CALLED','IN_CONSULTATION','COMPLETED','CANCELLED','NO_SHOW'].map(x=>({value:x,label:x.replaceAll('_',' ')})))}{select('providerId','Doctor',providers.map(p=>({id:p.id,label:`${p.firstName} ${p.lastName}`})),false)}{select('priority','Priority',['NORMAL','URGENT','STAT'].map(x=>({value:x,label:x})))}{field('notes','Notes')}</>}
 {type==='ward-transfer'&&<>{select('admissionId','Active admission',admissions.map(a=>({id:a.id,label:`${a.admissionNumber} · ${a.patient?.firstName||''} ${a.patient?.lastName||''} · ${a.ward?.name||''}`})))}{select('toWardId','Destination ward',wards.map(w=>({id:w.id,label:`${w.code} · ${w.name}`})))}<label>Destination bed<select value={form.toBedId||''} onChange={e=>set('toBedId',e.target.value)} required><option value=''>Select available bed</option>{wards.flatMap(w=>(w.beds||[]).filter(b=>b.status==='AVAILABLE').map(b=>({id:b.id,label:`${w.name} · ${b.bedNumber}`}))).map(b=><option key={b.id} value={b.id}>{b.label}</option>)}</select></label>{field('reason','Reason')}</>}
 {type==='nursing-task'&&!editing&&<>{select('patientId','Patient',patients.map(p=>({id:p.id,label:`${p.patientNumber} · ${p.firstName} ${p.lastName}`})))}{select('admissionId','Admission',admissions.map(a=>({id:a.id,label:`${a.admissionNumber} · ${a.ward?.name||''} · ${a.bed?.bedNumber||''}`})),false)}{select('assignedToId','Assigned nurse/clinician',providers.map(p=>({id:p.id,label:`${p.firstName} ${p.lastName}`})),false)}{field('taskType','Task type','text',{required:true})}{select('priority','Priority',['NORMAL','URGENT','STAT'].map(x=>({value:x,label:x})))}{field('dueAt','Due time','datetime-local')}{field('notes','Instructions')}</>}{type==='nursing-task'&&editing&&<>{select('status','Status',['OPEN','IN_PROGRESS','COMPLETED','CANCELLED'].map(x=>({value:x,label:x.replaceAll('_',' ')})))}{select('assignedToId','Assigned nurse/clinician',providers.map(p=>({id:p.id,label:`${p.firstName} ${p.lastName}`})),false)}{select('priority','Priority',['NORMAL','URGENT','STAT'].map(x=>({value:x,label:x})))}{field('dueAt','Due time','datetime-local')}{field('notes','Instructions')}</>}
 {type==='patient'&&!editing&&<>{field('firstName','First name','text',{required:true})}{field('middleName','Middle name')}{field('lastName','Last name','text',{required:true})}{field('phone','Phone')}{field('email','Email','email')}{field('dateOfBirth','Date of birth','date')}{select('sex','Sex',[{value:'MALE',label:'Male'},{value:'FEMALE',label:'Female'},{value:'OTHER',label:'Other'},{value:'UNKNOWN',label:'Unknown'}])}{select('departmentId','Department',deps)}</>}
 {type==='blood'&&<>{field('unitNumber','Unit number','text',{required:true})}{field('donorName','Donor name','text',{required:true})}{field('donorPhone','Donor phone')}{select('bloodGroup','Blood group',['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(x=>({value:x,label:x})))}{select('component','Component',['WHOLE_BLOOD','PACKED_RBC','PLASMA','PLATELETS','CRYOPRECIPITATE'].map(x=>({value:x,label:x.replaceAll('_',' ')})))}{field('volumeMl','Volume (mL)','number',{min:1,max:1000,required:true})}{field('collectedAt','Collection date/time','datetime-local',{required:true})}{field('expiresAt','Expiry date/time','datetime-local',{required:true})}{select('status','Status',statuses.blood.map(x=>({value:x,label:x.replaceAll('_',' ')})))}{field('notes','Notes')}</>}
 {type==='patient'&&editing&&<>{field('firstName','First name','text',{required:true})}{field('middleName','Middle name')}{field('lastName','Last name','text',{required:true})}{field('phone','Phone')}{field('email','Email','email')}{field('address','Address')}{select('sex','Sex',[{value:'MALE',label:'Male'},{value:'FEMALE',label:'Female'},{value:'OTHER',label:'Other'},{value:'UNKNOWN',label:'Unknown'}])}{select('status','Status',statuses.patient.map(x=>({value:x,label:x.replaceAll('_',' ')})))}</>}
 {!editing&&['appointment','encounter','lab','radiology','prescription','admission'].includes(type)&&<>{select('patientId','Patient',patients.map(p=>({id:p.id,label:`${p.patientNumber} · ${p.firstName} ${p.lastName}`})))}{!['prescription','admission'].includes(type)&&select('departmentId','Department',deps)}</>}
 {type==='appointment'&&!editing&&<>{field('scheduledAt','Scheduled time','datetime-local',{required:true})}{field('reason','Reason')}</>}{type==='appointment'&&editing&&select('status','Status',statuses.appointment.map(x=>({value:x,label:x.replaceAll('_',' ')})))}
 {type==='encounter'&&!editing&&<>{select('type','Encounter type',['OPD','EMERGENCY','INPATIENT','MATERNITY','SURGERY','FOLLOW_UP','SPECIALTY'].map(x=>({value:x,label:x.replaceAll('_',' ')})))}{field('chiefComplaint','Chief complaint')}</>}{type==='encounter'&&editing&&<>{select('status','Status',statuses.encounter.map(x=>({value:x,label:x.replaceAll('_',' ')})))}{field('assessment','Assessment')}{field('plan','Plan')}</>}
 {type==='lab'&&!editing&&<>{field('testName','Test name','text',{required:true})}{select('priority','Priority',['ROUTINE','URGENT','STAT'].map(x=>({value:x,label:x})))}{field('specimen','Specimen')}</>}{type==='lab'&&editing&&select('status','Status',statuses.lab.map(x=>({value:x,label:x.replaceAll('_',' ')})))}
 {type==='radiology'&&!editing&&<>{field('modality','Modality','text',{required:true})}{field('studyName','Study','text',{required:true})}{select('priority','Priority',['ROUTINE','URGENT','STAT'].map(x=>({value:x,label:x})))}{field('clinicalIndication','Clinical indication')}</>}{type==='radiology'&&editing&&<>{select('status','Status',statuses.radiology.map(x=>({value:x,label:x.replaceAll('_',' ')})))}{field('reportText','Report')}</>}
 {type==='prescription'&&!editing&&<>{select('medicationId','Medication',meds.map(m=>({id:m.id,label:`${m.name} ${m.strength||''} · Stock ${m.stockQty}`})))}{field('dose','Dose','text',{required:true})}{field('frequency','Frequency','text',{required:true})}{field('duration','Duration','text',{required:true})}{field('quantity','Quantity','number',{required:true,min:1})}{field('instructions','Instructions')}</>}{type==='prescription'&&editing&&select('status','Status',statuses.prescription.map(x=>({value:x,label:x.replaceAll('_',' ')})))}
 {type==='vitals'&&<>{select('patientId','Patient',patients.map(p=>({id:p.id,label:`${p.patientNumber} · ${p.firstName} ${p.lastName}`})))}{field('temperature','Temperature °C','number')}{field('pulse','Pulse / min','number')}{field('respiratoryRate','Respiratory rate / min','number')}{field('systolic','Systolic BP','number')}{field('diastolic','Diastolic BP','number')}{field('oxygenSaturation','Oxygen saturation %','number')}{field('weight','Weight kg','number')}{field('height','Height cm','number')}</>}
 {type==='medication'&&<>{field('code','Code','text',{required:true})}{field('name','Name','text',{required:true})}{field('genericName','Generic name')}{field('strength','Strength')}{field('form','Form')}{field('stockQty','Stock quantity','number',{min:0,required:true})}{field('reorderAt','Reorder level','number',{min:0,required:true})}{select('active','Status',[{value:'true',label:'Active'},{value:'false',label:'Inactive'}])}</>}
 {type==='admission'&&!editing&&<>{select('wardId','Ward',wards.map(w=>({id:w.id,label:`${w.code} · ${w.name} · ${(w.beds||[]).filter(b=>b.status==='AVAILABLE').length} available`})))}<label>Bed<select value={form.bedId||''} onChange={e=>set('bedId',e.target.value)} required><option value=''>{selectedWard?'Select available bed':'Select ward first'}</option>{availableBeds.map(b=><option key={b.id} value={b.id}>{b.bedNumber}{b.bedType?` · ${b.bedType}`:''} · {b.status}</option>)}</select></label>{select('encounterId','Encounter',patientEncounters.filter(e=>!['CANCELLED','COMPLETED'].includes(e.status)).map(e=>({id:e.id,label:`${e.encounterNumber||'ENC'} · ${e.type||''} · ${e.startedAt?new Date(e.startedAt).toLocaleString():''}`})),'Optional — link an existing encounter',false)}</>}{type==='admission'&&editing&&<>{select('status','Status',statuses.admission.map(x=>({value:x,label:x.replaceAll('_',' ')})))}{field('dischargeSummary','Discharge summary')}</>}
 <div className="modal-actions"><button type="button" className="secondary" onMouseDown={e=>e.preventDefault()} onClick={e=>{e.preventDefault();e.stopPropagation();onClose()}}>Cancel</button><button className="primary" disabled={busy}>{busy?(editing?'Saving…':'Creating…'):(editing?'Save changes':'Create record')}</button></div></form></div></div>
